import 'dart:ui';import 'package:flutter/material.dart';import '../../../../Core/Utils/Extensions/responsive_extension.dart';import '../../../../Config/app_config.dart';import 'authentication_split1.dart';import 'authentication_split2.dart';class AuthenticationBody extends StatelessWidget {  const AuthenticationBody({    super.key,  });  @override  Widget build(BuildContext context) {    List<Widget> list = [      AuthenticationSplit1(),      AuthenticationSplit2(),    ];    return Scaffold(      body: SafeArea(        child: CustomScrollView(          physics: AppConfig.physicsCustomScrollView,          slivers: [            SliverFillRemaining(                hasScrollBody: false,                fillOverscroll: true,                child: BackdropFilter(                  filter: ImageFilter.blur(sigmaX: 10.0, sigmaY: 10.0),                  child: Container(                    color: Colors.white,                    child: context.isSmallScreen                        ? Stack(                            children: list,                          )                        : Row(                          children: list,                        ),                  ),                ))          ],        ),      ),    );  }}